referenceSolutions.python:
def risingLabelsThresholdFile(readings, k):
    a=readings
    out=[]
    from bisect import bisect_left
    tails=[]
    for x in a:
        i=bisect_left(tails,x)
        if i==len(tails): tails.append(x)
        else: tails[i]=x
        out.append(i+1)
    return sum(x>=k for x in out)

